Definition putA_frames (m : mem) (sp : word) (spa1 ff1 fp1 spa2 ff2 fp2 rd cbp E : Z) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word)
    (gap1 gap2 : list cell) (j0 j24 h80 k0 k32 k64 h72 : list byte) : Prop :=
  rw_cells bsegs m spa1 (put_locals1 ff1 j0 j24)
  /\ rw_cells bsegs m (spa1 + 64) gap1 /\ Z.of_nat (cells_size gap1) = bv_unsigned sp + -96 - (spa1 + 64)
  /\ rw_cells bsegs m (bv_unsigned sp + -96) (put_saves s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
  /\ rw_cells bsegs m ff1 (put_ffa spa1) /\ rw_cells bsegs m (ff1 + 80) [CB 40 h80; C8 (Z_to_bv 64 fp1)]
  /\ rw_cells bsegs m (Z.shiftr ff1 3 + 2147450880) put_sh1 /\ rw_cells bsegs m fp1 [C1 (b8 1)]
  /\ rw_cells bsegs m spa2 (dbp_locals1 (Z_to_bv 64 7) E ff2 k0 k32 k64)
  /\ rw_cells bsegs m (spa2 + 88) gap2 /\ Z.of_nat (cells_size gap2) = spa1 + -104 - (spa2 + 88)
  /\ rw_cells bsegs m (spa1 + -104) (prep_saves s11 (Z_to_bv 64 (Z.shiftr rd 3 + 2147450880)) (Z_to_bv 64 2147450880) (Z_to_bv 64 ff1)
                                         (Z_to_bv 64 (Z.shiftr ff1 3 + 2147450880)) (Z_to_bv 64 (ff1 + 32)) (Z_to_bv 64 E) (Z_to_bv 64 cbp) (Z_to_bv 64 rd)
                                         (Z_to_bv 64 ff1) (Z_to_bv 64 spa1) sp (Z_to_bv 64 P_A_PUT_RET1))
  /\ rw_cells bsegs m ff2 (dbp_ffa spa2) /\ rw_cells bsegs m (ff2 + 72) [CB 48 h72; C8 (Z_to_bv 64 fp2)]
  /\ rw_cells bsegs m (Z.shiftr ff2 3 + 2147450880) dbp_sh1 /\ rw_cells bsegs m fp2 [C1 (b8 1)].

