Definition putB_W (lo spa1 E b : Z) (es : list mbe) (insz n x ff1 fp1 ff2 fp2 : Z) : list (Z * Z) :=
  [(lo, spa1 + 64); (E, E + 24); (b + 24, b + 64);
   (fst (mb_b1 b es insz n x), fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x));
   (fst (mb_b2 b es insz n x), fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x));
   (ff1, ff1 + 128); (sh ff1, sh ff1 + 16); (fp1, fp1 + 1); (ff2, ff2 + 128); (sh ff2, sh ff2 + 16); (fp2, fp2 + 1)]%Z.

Definition putB_post (ra sp gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
